"""CarPlay product page. Editorial diagrams are not device screenshots."""
from html import escape


def render_carplay(lang, email):
    zh = lang == 'zh'
    t = lambda a, b: a if zh else b
    base = '/memory-music-support/'
    home = base if zh else base + 'en/'
    alt = base + ('en/carplay/' if zh else 'carplay/')
    art = base + 'assets/' + ('' if zh else 'en/')
    entries = [
        ('01', t('首页','Home'), t('接着上一次，继续听。','Pick up where you left off.'), t('从正在播放、最近播放、喜欢的音乐和播放队列，回到熟悉的旋律。','Return to familiar music through Now Playing, Recently Played, Favorites and your play queue.')),
        ('02', t('歌单','Playlists'), t('出发前整理，路上聆听。','Make a playlist. Take it along.'), t('手动编排的歌单，与按规则生成的智能歌单，都有自己的入口。','Your hand-picked playlists and rule-based smart playlists each have a place.')),
        ('03', t('标签','Tags'), t('用自己的方式找歌。','Find music in your own words.'), t('从“在路上”到“日落时分”，按你在手机中整理的标签浏览歌曲。','Browse the tags you organize on your phone, from On the Road to Sunset.')),
        ('04', t('音乐库','Library'), t('自己的收藏，随车同行。','Your collection comes along.'), t('浏览全部歌曲，也可以按艺术家和专辑，找到想听的那一首。','Browse all songs, or find a favorite by artist and album.')),
    ]
    tiles = ''.join(f'<article><span class="cp-number">{n}</span><h3>{name}</h3><h4>{title}</h4><p>{body}</p></article>' for n,name,title,body in entries)
    faq = [
        (t('CarPlay 需要额外购买吗？','Is CarPlay a separate purchase?'), t('CarPlay 包含在 Memory Music Pro 中。月订阅、年订阅和永久买断解锁同一套 Pro 功能，无需另购 CarPlay。','CarPlay is included with Memory Music Pro. Monthly, yearly and lifetime options unlock the same Pro features; no separate CarPlay purchase is needed.')),
        (t('Mac 中的音乐会自动出现在车里吗？','Does music on my Mac automatically appear in my car?'), t('不会。CarPlay 使用连接的 iPhone 上可访问的本地音频。iCloud 只同步整理信息，不传输原始音频；请先在 iPhone 准备音乐并检查目录权限。','No. CarPlay uses local audio accessible on the connected iPhone. iCloud syncs organization information, not original audio. Prepare the music on your iPhone and check folder access first.')),
        (t('一定需要网络才能播放吗？','Does playback always need an internet connection?'), t('已经下载到 iPhone、并且 App 有权读取的本地音乐，不依赖流媒体服务。尚在云端、未下载或授权失效的文件，需要先在 iPhone 上处理。','Local music already downloaded to your iPhone and accessible to the app does not depend on a streaming service. Cloud-only, undownloaded or inaccessible files need attention on your iPhone first.')),
        (t('支持哪些车载设备？','Which vehicles are compatible?'), t('需要支持 Apple CarPlay 的 iPhone、车型或车载系统。连接方式与显示布局取决于你的设备、系统版本和车机；请查看 Apple 设置指南及车辆说明书。','You need an iPhone and vehicle or head unit compatible with Apple CarPlay. Connection methods and layouts depend on your devices, software and vehicle. See Apple’s setup guide and your vehicle manual.')),
    ]
    faqs = ''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in faq)
    return f'''<!doctype html><html lang="{'zh-CN' if zh else 'en'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Memory Music · CarPlay</title><meta name="description" content="{t('把自己的本地音乐带上路。了解 Memory Music Pro 的 CarPlay 浏览、歌单、标签与播放控制。','Take your local music along. Explore CarPlay browsing, playlists, tags and playback controls with Memory Music Pro.')}"><meta name="theme-color" content="#fbfbfd"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'self'; form-action 'none'"><link rel="icon" href="{base}icon.png"><link rel="stylesheet" href="{base}product.css"><link rel="stylesheet" href="{base}carplay.css"></head><body class="cp-page"><a class="skip" href="#main">{t('跳至正文','Skip to content')}</a><header class="site-header"><div class="nav-wrap"><a class="brand" href="{home}"><img src="{base}icon.png" width="32" height="32" alt="">Memory Music</a><nav aria-label="{t('主导航','Main navigation')}"><a href="{home}">{t('产品','Overview')}</a><a href="#explore">{t('CarPlay 亮点','Explore')}</a><a href="{home}#pricing">Pro</a><a class="lang" href="{alt}">{t('EN','中文')}</a></nav></div></header><main id="main">
<section class="cp-hero section"><p class="eyebrow">MEMORY MUSIC PRO · CARPLAY</p><h1>{t('一路向前。<br>一路好音乐。','The road ahead.<br>The music you love.')}</h1><p class="cp-lead">{t('把自己的音乐，带上下一段旅程。','Bring your own collection along for the drive.')}</p><p class="cp-sub">{t('从歌单、标签和音乐库出发，<br>在 CarPlay 中继续聆听熟悉的旋律。','Your playlists. Your tags. Your library.<br>A familiar way to keep listening with CarPlay.')}</p><a class="text-link" href="#explore">{t('探索 CarPlay','Explore CarPlay')} ↓</a>
<figure class="cp-stage"><div class="cp-journey" aria-label="{t('CarPlay 功能示意','CarPlay feature illustration')}"><div class="cp-orbit"><span class="cp-orbit-line"></span><span class="cp-marker">♫</span><span class="cp-destination"></span></div><div class="cp-demo"><div class="cp-demo-heading"><span>MEMORY MUSIC</span><span>CARPLAY</span></div><div class="cp-demo-content"><div class="cp-cover" aria-hidden="true"><span>♪</span></div><div><p class="cp-small">{t('继续聆听','KEEP LISTENING')}</p><h2>{t('在路上的歌','Songs for the road')}</h2><p>{t('自己的收藏 · 下一段旅程','Your collection · Your next journey')}</p><div class="cp-control-icons" aria-hidden="true"><span>↶</span><span>Ⅱ</span><span>↷</span></div></div></div><div class="cp-demo-tabs"><span>{t('首页','Home')}</span><span>{t('歌单','Playlists')}</span><span>{t('标签','Tags')}</span><span>{t('音乐库','Library')}</span></div></div></div><figcaption>{t('功能示意图，非车机截图。实际界面与可用操作随 iOS 和车载系统而异。','Feature illustration, not a vehicle screenshot. Actual layouts and available controls vary by iOS and CarPlay system.')}</figcaption></figure></section>
<section class="cp-explore section" id="explore"><div class="section-heading"><p class="eyebrow">{t('熟悉的收藏，熟悉的入口','FAMILIAR MUSIC. FAMILIAR PLACES.')}</p><h2>{t('少一点寻找。<br>多一点好好听。','Less searching.<br>More listening.')}</h2><p>{t('在手机上认真整理，在车载屏幕上找到它们。','Organize on your phone. Find your favorites on the car display.')}</p></div><div class="cp-feature-grid">{tiles}</div></section>
<section class="cp-playback"><div class="section cp-playback-inner"><div><p class="eyebrow">{t('正在播放','NOW PLAYING')}</p><h2>{t('下一首，<br>顺着心情来。','Let the next song<br>follow the mood.')}</h2><p>{t('通过 CarPlay 系统播放界面暂停、继续或切换歌曲。随机播放、循环和喜欢，让熟悉的操作延续到车里；也可以打开当前播放队列。','Pause, resume and skip through the system CarPlay player. Shuffle, repeat and favorite controls bring familiar choices along, with access to your current play queue.')}</p><p class="fine">{t('右图为真实 iPhone 播放界面渲染，使用虚构歌曲与原创封面；并非车机画面。','Shown: an actual iPhone player render with a fictional song and original artwork, not a CarPlay display.')}</p></div><figure class="cp-phone"><img src="{art}iphone-player.png" width="1206" height="2622" alt="{t('Memory Music iPhone 播放界面，示例歌曲','Memory Music iPhone player with a sample song')}" loading="lazy"></figure></div></section>
<section class="cp-setup section"><div class="section-heading left"><p class="eyebrow">{t('出发前，准备好','BEFORE YOU SET OFF')}</p><h2>{t('三步，带上自己的音乐。','Bring your music along.')}</h2></div><ol><li><span>01</span><div><h3>{t('在 iPhone 准备音乐','Prepare your music on iPhone')}</h3><p>{t('添加自己的音频，确认歌曲已下载、目录访问正常。出发前整理好歌单和标签。','Add your audio, make sure songs are downloaded and folder access works, then organize playlists and tags before the drive.')}</p></div></li><li><span>02</span><div><h3>{t('确认 Pro 已解锁','Check that Pro is unlocked')}</h3><p>{t('CarPlay 是 Pro 功能。已有购买可使用同一 Apple 账户，在 App 设置中恢复购买。','CarPlay requires Pro. Restore an existing purchase in the app’s settings using the same Apple Account.')}</p></div></li><li><span>03</span><div><h3>{t('连接支持 CarPlay 的车载系统','Connect to a compatible CarPlay system')}</h3><p>{t('按车辆说明完成连接，在 CarPlay 中打开 Memory Music。具体连接方式请查看 Apple 指南。','Follow your vehicle’s connection instructions, then open Memory Music in CarPlay. See Apple’s guide for connection details.')}</p><a class="text-link" href="https://support.apple.com/{'zh-cn' if zh else 'en-us'}/108415">{t('Apple CarPlay 设置指南','Apple CarPlay setup guide')} ↗</a></div></li></ol><p class="cp-note">{t('请在停车时完成导入、授权和账户设置。驾驶时遵守当地法规并专注路况。','Complete imports, permissions and account setup while parked. Follow local laws and keep your attention on the road.')}</p></section>
<section class="faq section"><div><p class="eyebrow">{t('出发前还想知道','GOOD TO KNOW')}</p><h2>{t('关于 CarPlay。','About CarPlay.')}</h2></div><div class="faq-list">{faqs}</div></section>
<section class="closing section"><p class="eyebrow">MEMORY MUSIC PRO</p><h2>{t('让喜欢的歌，<br>陪你去更远的地方。','Take your favorites<br>a little further.')}</h2><p>{t('CarPlay 包含在月订阅、年订阅和永久买断中。<br>App 正在准备正式发行，尚未开放下载。','CarPlay is included with monthly, yearly and lifetime Pro.<br>The app is preparing for release. Downloads are not yet available.')}</p><a class="pill" href="{home}#pricing">{t('了解免费与 Pro','Explore Free & Pro')} ›</a><p class="fine">{t('本页介绍当前实现的功能；正式版实车兼容性验收仍在进行中。','This page describes implemented features. Release validation with physical CarPlay systems is still in progress.')}</p></section></main><footer><div class="footer-inner"><a class="brand" href="{home}">Memory Music</a><nav aria-label="{t('页脚导航','Footer navigation')}"><a href="{home}">{t('产品介绍','Overview')}</a><a href="{home}privacy/">{t('隐私政策','Privacy')}</a><a href="{home}support/">{t('使用支持','Support')}</a><a href="mailto:{escape(email)}">{escape(email)}</a></nav><small>© 2026 Ken Shane · CarPlay is a trademark of Apple Inc.</small></div></footer></body></html>'''
